DROP = {"Philadelphia Museum of Art","Penn Museum online collections","Polona (National Library of Poland)","Iconclass","id.loc.gov (LC Linked Data Service)","Old Maps Online","Internet Archive Scholar","Knowledge Commons (formerly Humanities Commons) Works","Free Music Archive","Leaflet","Observable Plot","COLMAP","Gephi","Tropy","GIMP / Krita","Audacity"}
rows = [r for r in rows if r[0] not in DROP]
rows = [(("D3.js / Observable Plot",) + tuple(r[1:])) if r[0]=="D3.js" else r for r in rows]

with open(OUT, "w", newline="", encoding="utf-8") as f:
    w = csv.writer(f, quoting=csv.QUOTE_MINIMAL)
    w.writerow(HEADER)
    for i, r in enumerate(rows, 1):
        assert len(r) == 14, (i, r[0], len(r))
        r = list(r)
        worlds = [x for x in r[2].split(";") if x and x != "GL"]
        r[2] = ";".join(worlds) if worlds else ALLW
        if r[4] == "GL":
            r[4] = "Web portal/collection (see verification_url or site)"
        assert r[5].split(" ")[0].rstrip(",") in ("free","free-with-key","free-with-registration","free-limited","paid","unverified"), (r[0], r[5])
        assert r[8] in ("yes","no","per-item"), (r[0], r[8])
        w.writerow([f"SRC{i:03d}"] + r)
print(len(rows))
